import React from 'react';

export default function TareaList({ tareas, onEliminar }) {
  return (
    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
      {tareas.length === 0 ? (
        <p className="text-center text-gray-500">No hay tareas registradas.</p>
      ) : (
        tareas.map((tarea) => (
          <div key={tarea.id} className="p-4 border rounded flex justify-between items-center">
            <div>
              <h3 className="font-bold">{tarea.entidadMunicipalNombre}</h3>
              <p>{tarea.descripcion}</p>
            </div>
            <button
            onClick={() => {
              if (window.confirm("¿Estás seguro de eliminar esta tarea?")) {
                onEliminar(tarea.id);
                toast.info("Tarea eliminada");
              }
            }}
            className="bg-red-500 text-white px-3 py-1 rounded"
            >
              Eliminar
            </button>

          </div>
        ))
      )}
    </div>
  );
}
